def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = sum(1 for h in history if h[1] == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for h in history if h[0] == 'C')
    my_d = n - my_c

    last_me, last_opp = history[-1]

    if opp_d == 0:
        return 'C'

    if opp_c == 0:
        return 'D'

    if n >= 2 and history[-1][1] == history[-2][0]:
        return 'C'

    if opp_c <= n // 4:
        if last_me == 'D' and last_opp == 'D':
            if rng.random() < 0.3:
                return 'C'
        return 'D'

    if opp_c >= 3 * n // 4:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        else:
            if rng.random() < 0.1:
                return 'C'
            return 'D'
    else:
        return 'C'
